"use strict";(globalThis.webpackChunkztools_docs=globalThis.webpackChunkztools_docs||[]).push([[75556],{87679(e){e.exports=JSON.parse('{"id":"capacitor-auth-manager","name":"Capacitor Auth Manager","url":"https://www.npmjs.com/package/capacitor-auth-manager","platforms":["npm package"],"logo":"/ecosystem/capacitor-auth-manager.svg","card":"For app developers: Google sign-in on web, Android and iOS from one call, with no Firebase dependency.","title":"Capacitor Auth Manager: one Google sign-in call for three platforms","intro":"Capacitor Auth Manager is an npm package that gives a Capacitor app one Google sign-in call for web, Android and iOS. It does not need Firebase as a dependency.","sections":[["Who is it for?","Developers building with Capacitor. If you use ZTools to format a JSON response while you build, this sits further along the same job: signing people in to the app you are making."],["Which providers does it support?","Google. It is the only provider switched on in version 3.x."],["Why does Firebase matter here?","Some apps do not use Firebase at all. With this package, Google sign-in does not pull it in."]]}')}}]);